from curation_helpers import *
N65='第65课p32-b006至p45-b002全课逐段审读，二次重读p32-34定义与p37/p39技术补充。正文、作者另日附文、读者答案分别识别；p39蓝色新文章标题已在渲染页确认，非前一CCTV身份延续。文字命题不以编者后加图说明作证。'
add('l065-n-inclusion-up','用[di,gi]表示第i根K线低高区间时，向上方向顺次处理的n根包含K线组等价为[max di,max gi]的新K线。',['包含关系','包含处理'],['p0032-b009'],1,'推广向上包含处理到顺序K线组',conditions=['向上方向','按顺序法则处理包含组'],relations=[('包含处理','包含关系','requires')],note=N65+'与b010顺序规则并读，未忽略包含关系不传递的限制。')
add('l065-n-inclusion-down','用[di,gi]表示第i根K线低高区间时，向下方向顺次处理的n根包含K线组等价为[min di,min gi]的新K线。',['包含关系','包含处理'],['p0032-b009'],1,'推广向下包含处理到顺序K线组',conditions=['向下方向','按顺序法则处理包含组'],relations=[('包含处理','包含关系','requires')],note=N65+'最大/最小公式的方向与上下界已二次核对。')
add('l065-inclusion-not-transitive','K线包含关系不满足传递律：第1、2根包含且第2、3根包含，并不意味着第1、3根包含。',['包含关系'],[('p0032-b010','包含关系，不符合传递律，也就是说，第1、2根K线是包含关系，第2、3根也是包含关系，但并不意味着第1、3根就有包含关系。')],1,'防止错误跨K线合并的关键边界',note=N65)
add('l065-inclusion-sequential','包含处理须按顺序：先由第1、2根确认合并K线，再将合并结果与第3根比较；仍包含则继续合并，否则按正常K线处理。',['包含处理','结合律'],[('p0032-b010','还要遵守顺序原则，就是先用第1、2根K线的包含关系确认新的K线，然后用新的K线去和第三根比，如果有包含关系，继续用包含关系的法则结合成新的K线，如果没有，就按正常K线去处理。')],1,'给出确定性包含处理算法和停止条件',relations=[('包含处理','结合律','requires')],note=N65)
add('l065-inclusion-direction-up','若第n根与n+1根包含，而与n-1根不包含，且gn≥gn-1，则称这三根K线的方向向上。',['包含处理','包含关系'],['p0032-b012'],1,'为向上包含处理给出严格方向前提',conditions=['第n根与n+1根包含','第n根与n-1根不包含','gn≥gn-1'],relations=[('包含处理','包含关系','requires')],note=N65+'没有把等号任意删除，也未允许前一对仍包含的场景套用。')
add('l065-inclusion-direction-down','若第n根与n+1根包含，而与n-1根不包含，且dn≤dn-1，则称这三根K线的方向向下。',['包含处理','包含关系'],['p0032-b012'],1,'为向下包含处理给出严格方向前提',conditions=['第n根与n+1根包含','第n根与n-1根不包含','dn≤dn-1'],relations=[('包含处理','包含关系','requires')],note=N65)
add('l065-direction-mutual-exclusion','在第n根与n-1根不包含的前提下，gn≥gn-1与dn≤dn-1不可能同时成立；gn<gn-1且dn>dn-1反而属于包含关系，违反前提。',['包含关系','包含处理'],['p0032-b013','p0033-b000'],1,'方向定义前提的必要排除与定义同级',conditions=['第n根与n-1根不包含'],note=N65+'已补齐跨页续句，保留包含假设而不把不等式结论无条件化。')
add('l065-formed-bars-unique-fractals','对已经走出来的K线，按统一几何定义可当下唯一确定分型；确定结果不因分析者或事后时间而改变。',['分型','当下性'],['p0033-b001','p0033-b002'],1,'分型客观唯一性及已形成K线前提',conditions=['被分析K线已经走出来','对象与周期图固定','按统一定义'],relations=[('当下性','分型','qualifies')],note=N65+'区别已形成K线与尚未生成的未来K线，不把未完成结构预标当成不可修改的确认。')
add('l065-no-fractal-do-not-force','在所选周期图上没有符合定义的分型就应判为没有；若需更精细观察，可以换用更小周期图。',['分型','周期K线图'],[('p0033-b003','确定显微镜的倍数，就按看到的K线用定义严格来，没有符合定义的，就是没有，就这么简单。如果希望能分析得更精确，那就用小级别的图')],2,'给出粗周期缺少分型时的判定和观察方法',relations=[('分型','周期K线图','qualifies')],note=N65)
add('l065-chart-not-operation-level','使用哪种周期图与采用哪种操作级别没有必然关系；看1分钟图不意味着必须做超短线，也可用于定位年线级别背驰。',['周期K线图','操作级别','背驰'],[('p0033-b003','用什么图与以什么级别操作没任何必然关系，用1分钟图，也可以找出年线级别的背驰，然后进行相应级别的操作。看1分钟图，并不意味着一定要玩超短线')],1,'明确观察周期与操作级别不可混同',relations=[('周期K线图','操作级别','distinguishes')],note=N65)
add('l065-same-type-fractals-not-one-stroke','两个顶或两个底不能组成一笔；若中间还有其他顶底，说明跨了多笔；若没有其他顶底，前一个顶或底后的转折太小，可以忽略前一个分型。',['笔','顶分型','底分型'],['p0033-b004'],1,'笔端点异性要求及同类分型处理边界',conditions=['一笔须一顶一底'],relations=[('笔','顶分型','requires'),('笔','底分型','requires')],note=N65+'第77课还有极值筛选的更详细算法，将另行并列，未把本段简略说法替代后课。')
add('l065-strokes-alternate-unique','处理不构成有效转折的分型后，所有图形可唯一分解为上下交替连接的笔；有效分型为相邻上下两笔的连接。',['笔','分型'],['p0033-b005','p0034-b000'],1,'给出笔分解唯一性和连接结构',conditions=['遵守一顶一底及分型处理规则'],relations=[('笔','分型','requires')],note=N65+'补齐p33-34续句；不将共用连接分型与第62课单笔内部顶底共享K线混同。')
add('l065-segment-two-directions','线段至少有三笔，只分从向上一笔开始和从向下一笔开始两类。',['线段','笔'],['p0034-b001'],1,'线段方向和最小构成的基本分类',relations=[('线段','笔','composed_of')],note=N65)
add('l065-upward-stroke-destruction','向上线段的分型序列记为d1g1d2g2…时，若存在j≥i+2且dj≤gi，则称该向上线段被笔破坏。',['线段','笔破坏'],['p0034-b002'],1,'给出向上线段笔破坏的形式定义',conditions=['线段从向上一笔开始','j≥i+2','dj≤gi'],relations=[('笔破坏','线段','defines')],note=N65+'二次核对下标间距和≤，不把笔破坏直接等同线段确认结束。')
add('l065-downward-stroke-destruction','向下线段的分型序列记为g1d1g2d2…时，若存在j≥i+2且gj≥di，则称该向下线段被笔破坏。',['线段','笔破坏'],['p0034-b003'],1,'给出向下线段笔破坏的形式定义',conditions=['线段从向下一笔开始','j≥i+2','gj≥di'],relations=[('笔破坏','线段','defines')],note=N65)
add('l065-first-three-overlap','线段的前三笔必须有重叠部分；并不是任意连续三笔都构成线段。',['线段','笔'],['p0034-b004'],1,'线段最小构成的关键必要条件',conditions=['前三笔有重叠部分'],relations=[('线段','笔','requires')],note=N65)
add('l065-segment-decomposition-theorem','第65课线段分解定理称：线段被破坏，当且仅当至少被具有重叠部分的连续三笔中的一笔破坏；能构成重叠前三笔即必形成线段，故破坏充要条件是被另一线段破坏。',['线段分解定理','线段','线段破坏','笔破坏'],['p0034-b005'],1,'作者明确命名的核心线段定理',conditions=['连续三笔具有重叠部分','具体确认以后续67课特征序列精确标准为基础'],relations=[('线段分解定理','线段破坏','defines'),('线段破坏','笔破坏','qualifies')],note=N65+'和已审72课作者明确精确化说明并读，保留65原定理历史表述，不替代67两种情况。')
add('l065-divergence-requires-minimum-center','严格的背驰概念要求先有最低级别中枢和最低级别走势类型；线段以下只能讨论类似背驰的力度比较，不能当作真正背驰。',['背驰','类背驰','最小级别中枢','走势类型','线段'],[('p0037-b004','对背驰等概念，一定要存在最低级别的中枢后，才有最低级别的走势类型，才会有背驰等概念的存在，一般来说，在线段之下讨论背驰概念是没意义的，但可以根据类似背驰的力度比较方法来讨论线段之下类背驰的现象，但这和背驰是两回事情。')],1,'背驰和类背驰的存在条件及层级边界',relations=[('背驰','最小级别中枢','requires'),('背驰','走势类型','requires'),('背驰','类背驰','distinguishes')],note=N65)
add('l065-interval-nesting-below-segment','用区间套在线段以下定位买卖点时，实际使用的是类背驰力度比较；能够定位到极细价位不等于交易通道能够成交，过低级别操作还受成本限制。',['区间套','类背驰','操作级别'],[('p0037-b004','用区间套的方法，在定位线段之下的精确买卖点时，实际上用到的就是类背驰的力度比较'),('p0037-b004','特别对通道不顺的散户，就算你看到那价位，也不一定能买卖到。因此，不要用太低级别去操作')],2,'给出精细定位方法及交易执行限制',conditions=['定位低于线段层次','考虑交易通道和成本'],relations=[('区间套','类背驰','requires'),('操作级别','区间套','qualifies')],note=N65)
add('l065-line-not-minimum-sublevel','严格意义上，线段不是最小级别走势类型的次级别；把它这样称呼只是一种不严格的类似说法。',['线段','走势类型','级别'],[('p0039-b008','严格意义上说，把线段当成最小级别走势类型的次级别是不对的，当然，在不严格的意义上，可以类似地这样认为，但两者是有本质区别的。')],1,'明确线段与递归走势类型的核心层级边界',relations=[('线段','走势类型','distinguishes')],note=N65+'p39渲染页可见新作者文章标题和后续正文，排除前一读者答卷。')
add('l065-recursion-a0-practical-theoretical','中枢递归定义和分型、笔、线段方法的递归形式同为an=f(an-1)，区别在起始a0：纯理论从每笔实际成交起，而实用方法以分型、笔、线段确认可操作的最小级别起点，之后仍按递归定义。',['递归定义','分型','笔','线段','最小级别中枢'],['p0039-b009'],1,'解释理论存在性与实践构造之间的基本联系',conditions=['实际分笔成交不是定义中的“笔”'],relations=[('递归定义','最小级别中枢','qualifies'),('最小级别中枢','线段','requires')],note=N65+'二次核对作者特别区分实际“分笔成交”和几何“笔”；没有将二者合并。')

N66='第66课p45-b003至p50-b000完整逐段审读，正文宏观资金部分与p46-b004起市场附录分开，作者技术答疑逐个核查相邻发言者时间头；二次核对引文范围，未将读者问句作作者证据。'
add('l066-market-force-nonuniform','市场每刻走势由当下合力构成，现实中各分力并不等大；分析合力不能脱离对特别巨大分力的分析。',['市场合力','市场分力'],['p0045-b005'],2,'补充走势合力分析中资金力量差异的方法',relations=[('市场合力','市场分力','composed_of')],note=N66)
add('l066-dominant-force-stock','若一个分力远大于其他可忽略分力，市场合力基本等同该分力；高度控盘个股可出现这种情形，其稳定性可能突变。',['市场合力','市场分力','控盘'],['p0045-b006'],3,'说明单一巨大分力的特殊情形和稳定性限制',conditions=['其他分力相对可忽略'],relations=[('控盘','市场分力','qualifies')],note=N66)
add('l066-main-capital-factions','市场主力不是一拨统一控制每分每秒走势的人，主力资金有不同利益派别，既可能联手默契，也可能相互拆台。',['主力资金','市场分力'],['p0045-b007'],3,'澄清主力资金的多利益主体背景',relations=[('主力资金','市场分力','related')],note=N66)
add('l066-technical-not-main-capital-strategy','技术分析处理战术层面，不能单独解决主力资金运作的战略问题；技术是主力运作的基础之一。',['技术分析','主力资金'],[('p0045-b008','技术分析，不过是一些战术性问题，而战略性问题，就不是技术分析可以解决的。'),('p0045-b008','如果光把本ID的技术理论搞清楚，是运作不了主力资金的，当然，技术层面是一个基础，但只是一个方面。')],2,'界定技术体系在不同资金角色中的适用范围',relations=[('技术分析','主力资金','qualifies')],note=N66)
add('l066-main-funds-produce-points','无论何种资金，落实到走势上都是构造不同级别的买卖点；散户可依据合力结果识别买卖点，不必知道其制造过程。',['主力资金','买卖点','级别','市场合力'],[('p0045-b008','但无论什么资金，站在市场走势的角度，不过就是构造出不同级别的买卖点而已。因此，对于散户来说，你无须知道这天上掉下的馅饼是怎么制造的，只需要知道怎么才能吃到这馅饼。')],2,'将资金背景和实际技术操作连接到买卖点',relations=[('主力资金','买卖点','related'),('买卖点','级别','qualifies')],note=N66)
add('l066-main-funds-economic-trend','作者认为，任何背景和级别的主力资金最终都不能逆整个经济大势而行，必须随市场发展。',['主力资金','经济大势'],['p0045-b009','p0046-b000'],4,'记录作者宏观资金论的背景限制，不作为几何定理',relations=[('主力资金','经济大势','qualifies')],note=N66+'保留为作者市场观点而非现代实证结论；补齐跨页语句。')
add('l066-capital-food-chain','不同背景和势力资金控制不同板块，最大的几拨构成资金食物链上层；从上层到散户存在多层次，上层倾向维持对自己有利的生态平衡。',['主力资金','资金食物链','散户'],['p0046-b001','p0046-b003'],4,'完整保留本课主题的宏观背景模型',relations=[('资金食物链','主力资金','composed_of'),('资金食物链','散户','composed_of')],note=N66+'“绞杀/贵族”等比喻未转成可检验几何规则。')
add('l066-stroke-extremes','一笔是一顶一底，其顶和底必须分别是该笔的最高点和最低点；若内部超过这些极值，就不只一笔。',['笔','顶','底'],['p0047-b007'],1,'笔端点极值是防止误划的核心条件',relations=[('笔','顶','requires'),('笔','底','requires')],note=N66)
add('l066-standard-macd-two-components','标准情况下判断背驰和背驰段，应同时看MACD黄白线与柱子面积。',['背驰','背驰段','MACD'],['p0047-b010'],2,'明确MACD辅助判定的主要观察量',conditions=['标准情况'],relations=[('MACD','背驰','related')],note=N66+'p47-b009读者问柱高还是面积，作者并未只选面积；保留黄白线和面积同时看。')
add('l066-newcomer-larger-level','技术较弱的新手可扩大到30分钟以上乃至日线操作级别，减少交易次数，并避免强求每次成交在最优位置。',['操作级别','散户'],['p0047-b013'],2,'给出学习阶段选级别和执行预期的方法',conditions=['技术尚不熟练'],relations=[('操作级别','散户','qualifies')],note=N66)
add('l066-stroke-needs-standard-opposite-fractal','若后续走势一直处于顶分型第一根K线范围内，不能仅据此算新一笔；必须经非包含处理后找到标准底分型才可讨论。',['笔','底分型','包含处理'],['p0048-b004-s01','p0048-b005'],1,'笔成立所需对端分型的必要条件',conditions=['后续走势位于原顶分型首K线范围','后续经过非包含处理找到标准底分型'],relations=[('笔','底分型','requires'),('底分型','包含处理','requires')],note=N66+'读者p48-b004只提供所问情形，作者明确“不可以，除非”，故保持例外条件同级。')
add('l066-segment-trading-channel-limit','除非交易通道很好且判断十分精确，否则不宜过多参与线段层次操作，应至少采用1分钟以上级别。',['线段','操作级别'],['p0048-b008'],2,'线段交易方法的明确执行限制',conditions=['通道与精度不满足例外要求'],exceptions=['交易通道特别好且判断特别精确'],relations=[('操作级别','线段','qualifies')],note=N66)
add('l066-nine-types-combine-before-center','九个1分钟走势类型重叠后，5分钟中枢应按3+3+3组合后确定，点位不保证与另一递归观察相同。',['中枢','递归定义','结合律','走势类型'],['p0048-b010-s01','p0048-b011'],2,'补充九段组合升阶时的实际构造方法',conditions=['问题语境为九个1分钟走势类型重叠'],relations=[('中枢','结合律','requires')],note=N66+'作者回答“不一定。按3+3+3这样组合后确定5分钟的。”；p48-b010读者问题仅限定九个1分钟的指代。')
add('l066-macd-below-segment-insensitive','线段上的背驰只能是类背驰；类小转大由于时间短，不能只靠MACD判断。一般小转大有小平台，平台可能向下突破，宜待确认向上后介入。',['类背驰','小级别转大级别','MACD','线段'],['p0048-b014'],2,'给出低层次小转大判别方法及失败方向',conditions=['线段层次','时间过短导致MACD灵敏度不足'],exceptions=['小平台可以向下突破，不能预认向上'],relations=[('类背驰','线段','qualifies'),('小级别转大级别','MACD','qualifies')],note=N66)

N67='第67课p50-b001至p59-b004全部逐段审读；二次重读p50-51完整定义，补齐跨页第一种情况，问答核查明确作者头。实际查看p52-53：陈仁制作2008-08-14彩色后加图不能作2007作者规范证言；本批严格定义仅据课程文字，不借编者图新增规则。'
add('l067-feature-sequence-opposite-strokes','向上笔开始线段的特征序列为其中向下笔X1X2…Xn；向下笔开始线段的特征序列为其中向上笔S1S2…Sn。',['线段','特征序列','笔'],['p0050-b004'],1,'特征序列的基础定义决定线段划分',relations=[('特征序列','笔','composed_of'),('线段','特征序列','requires')],note=N67)
add('l067-feature-sequence-gap','特征序列中相邻两元素没有重合区间，称为该特征序列的一个缺口。',['特征序列','特征序列缺口'],[('p0050-b004','特征序列两相邻元素间没有重合区间，称为该序列的一个缺口。')],1,'两种线段结束情况的分支条件基础',relations=[('特征序列','特征序列缺口','defines')],note=N67+'特征序列缺口与成交K线跳空不同概念，未混同。')
add('l067-standard-feature-sequence','将特征序列每一元素视为K线，按一般K线分型方法处理包含关系；非包含处理后的序列称标准特征序列，后文未特别说明的“特征序列”都指它。',['特征序列','标准特征序列','包含处理'],['p0050-b005'],1,'确定特征序列分型判定的标准化输入',relations=[('标准特征序列','特征序列','defines'),('标准特征序列','包含处理','requires')],note=N67)
add('l067-feature-fractal-direction','向上笔开始线段的特征序列只考察顶分型，向下笔开始线段的特征序列只考察底分型。',['线段','特征序列','顶分型','底分型'],['p0050-b006'],1,'线段方向与特征分型的必要对应',conditions=['标准特征序列'],relations=[('特征序列','顶分型','qualifies'),('特征序列','底分型','qualifies')],note=N67)
add('l067-case-one-up-end','向上线段的标准特征序列出现顶分型，且该分型第一、第二元素间没有特征序列缺口时，线段在该顶分型高点结束。',['线段','标准特征序列','顶分型','特征序列缺口','线段破坏'],['p0050-b009',('p0051-b000','顶分型的高点处结束，该高点是该线段的终点；')],1,'向上线段第一种结束情况的核心判据',conditions=['标准特征序列顶分型已成立','分型第一、第二元素间无缺口'],relations=[('线段破坏','标准特征序列','requires'),('线段破坏','顶分型','requires')],note=N67+'跨p50-51续句补齐，不能只见局部新低或单笔破坏即判结束。')
add('l067-case-one-down-end','向下线段的标准特征序列出现底分型，且该分型第一、第二元素间没有特征序列缺口时，线段在该底分型低点结束。',['线段','标准特征序列','底分型','特征序列缺口','线段破坏'],[('p0051-b000','特征序列的底分型中，第一和第二元素间不存在特征序列的缺口，那么该线段在该底分型的低点处结束，该低点是该线段的终点；')],1,'向下线段第一种结束情况的核心判据',conditions=['标准特征序列底分型已成立','分型第一、第二元素间无缺口'],relations=[('线段破坏','底分型','requires')],note=N67)
add('l067-case-two-up-end','向上线段标准特征序列顶分型的第一、第二元素间有缺口时，须从该分型最高点起的向下一笔开始序列，其特征序列再出现底分型，才在原顶分型高点结束原线段。',['线段','标准特征序列','顶分型','底分型','特征序列缺口','线段破坏'],[('p0051-b002','特征序列的顶分型中，第一和第二元素间存在特征序列的缺口，如果从该分型最高点开始的向下一笔开始的序列的特征序列出现底分型，那么该线段在该顶分型的高点处结束，该高点是该线段的终点；')],1,'向上线段第二种结束情况的核心确认条件',conditions=['原特征顶分型第一、第二元素有缺口','反向序列特征底分型成立'],relations=[('线段破坏','特征序列缺口','qualifies'),('线段破坏','底分型','requires')],note=N67)
add('l067-case-two-down-end','向下线段标准特征序列底分型的第一、第二元素间有缺口时，须从该分型最低点起的向上一笔开始序列，其特征序列再出现顶分型，才在原底分型低点结束原线段。',['线段','标准特征序列','顶分型','底分型','特征序列缺口','线段破坏'],[('p0051-b002','特征序列的底分型中，第一和第二元素间存在特征序列的缺口，如果从该分型最低点开始的向上一笔开始的序列的特征序列出现顶分型，那么该线段在该底分型的低点处结束，该低点是该线段的终点；')],1,'向下线段第二种结束情况的核心确认条件',conditions=['原特征底分型第一、第二元素有缺口','反向序列特征顶分型成立'],relations=[('线段破坏','顶分型','requires')],note=N67)
add('l067-case-two-no-gap-fill-required','第二种情况的后一特征序列不一定封闭前序列相应缺口；第二序列只须出现分型，不再区分该分型属于第一还是第二种情况。',['线段破坏','特征序列缺口','特征序列','分型'],['p0051-b003'],1,'第二种情况的关键排除与确认规则同级',conditions=['原线段按第二种情况判断'],exceptions=['不要求后一特征序列封闭前一缺口','第二序列分型不再递归分第一/第二种'],relations=[('线段破坏','特征序列缺口','qualifies')],note=N67+'没有擅加回补缺口的必要性，也未无限递归要求第二序列的第二种情况。')
add('l067-feature-fractal-necessary','出现特征序列分型是线段结束的前提；第67课两种情况将“线段被线段破坏”精确化，此后线段划分以该精确定义为基础。',['线段破坏','特征序列','分型'],['p0051-b004'],1,'线段完成的必要前提和作者明确规范依据',relations=[('线段破坏','分型','requires'),('线段破坏','特征序列','requires')],note=N67+'与第72课明确回指67相互核对，历史关系有作者明文证据。')
add('l067-segment-unique-recursive-base','按上述标准，同一级别图上走势可唯一划为线段连接，正如可唯一划为笔连接；这两者是建立中枢和走势类型递归体系的基础。',['线段','笔','递归定义','中枢','走势类型'],['p0051-b006'],1,'给出线段唯一性及整个递归体系的基础关系',conditions=['相同品种和同一级别图','遵守本课两种划分标准'],relations=[('递归定义','线段','requires'),('递归定义','笔','requires')],note=N67)
add('l067-inclusion-only-if-contained','相邻K线只有存在包含关系才须合并；一根K线完全位于相邻K线区间内才是这里所说的包含。',['包含关系','包含处理'],['p0056-b004-s01','p0056-b005'],1,'作者对相等高低/麻点问题答疑给出的合并边界',relations=[('包含处理','包含关系','requires')],note=N67+'已核实b004尾嵌作者时间头拆为-s01，b005作者回复身份明确；没有根据读者列举的等值情形自行推断所有等号算法。')
add('l067-dynamic-position-building','建仓可以是动态过程，高明者在建仓时可不断降低成本；作者把成本未降到预定程度视为建仓尚未完成。',['动态建仓','成本'],['p0057-b010','p0057-b011'],3,'补充建仓方法和成本目标的实践含义',relations=[('动态建仓','成本','qualifies')],note=N67+'具体股票价格仅作背景，未推广作者个股保证。')
add('l067-moving-average-effective-break','作者给低熟练操作者的辅助策略是短线看5日线、中线看5周线、长线看5月线；有效跌破指跌破后相应级别的反抽仍不能回到该线，月线跌破至少须观察下月反抽，不能以一天判断。',['均线','操作级别','有效跌破'],['p0058-b002'],2,'给出均线辅助执行方法和对应级别的有效性条件',conditions=['作为低熟练操作者的辅助策略','反抽观察须与均线周期对应'],relations=[('有效跌破','均线','defines'),('均线','操作级别','qualifies')],note=N67+'这是明确作者市场附文中的一般方法，保留辅助及熟练程度语境，不冒充中枢定义。')
add('l067-maintain-shares-reduce-cost','在上涨震荡中通过先卖后买等操作降低成本，同时保持持仓筹码数量不变，可使现金增加并降低相对仓位，同时保留行情参与。',['成本','仓位','中枢震荡'],['p0058-b003'],3,'记录作者针对较大资金和熟练散户的成本管理方法',conditions=['能利用震荡差价','保持筹码数量不变'],relations=[('成本','仓位','related')],note=N67+'风险回避表述仅保留作者策略目的，未把“永远不败”修辞转为无风险保证。')
